int main(void) {
    char S[400005];
    if (scanf("%s", S) != 1) return 0;

    int L = (int)strlen(S);
    int N = L / 2;

    int *pairId = (int *)malloc(L * sizeof(int));
    int ca = 0, cb = 0;

    for (int i = 0; i < L; i++) {
        if (S[i] == 'a') {
            ca++;
            pairId[i] = ca;
        } else {
            cb++;
            pairId[i] = cb;
        }
    }

    int *chosen = (int *)calloc(N + 1, sizeof(int));
    char *ans = (char *)malloc((L + 1) * sizeof(char));
    int ansLen = 0;

    int p = 0;
    while (1) {
        int best = -1;
        int have = 0;

        for (int i = p; i < L; i++) {
            if (S[i] == 'b' && !chosen[pairId[i]]) {
                best = i;
                have = 1;
                break;
            }
        }
        if (!have) break;

        chosen[pairId[best]] = 1;

        for (int i = p; i <= best; i++) {
            if (chosen[pairId[i]]) ans[ansLen++] = S[i];
        }
        p = best + 1;
    }

    ans[ansLen] = '\0';
    printf("%s\n", ans);

    free(pairId);
    free(chosen);
    free(ans);
    return 0;
}

