public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String S = sc.next();
        int len = S.length();
        int N = len / 2;

        int[] posA = new int[N], posB = new int[N];
        int ai = 0, bi = 0;
        for (int i = 0; i < len; i++) {
            if (S.charAt(i) == 'a') posA[ai++] = i;
            else posB[bi++] = i;
        }

        String best = "";
        for (int mask = 0; mask < (1 << N); mask++) {
            boolean[] chosen = new boolean[len];
            for (int i = 0; i < N; i++) {
                if ((mask >> i & 1) == 1) {
                    chosen[posA[i]] = true;
                    chosen[posB[i]] = true;
                }
            }
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < len; i++) {
                if (chosen[i]) sb.append(S.charAt(i));
            }
            String candidate = sb.toString();
            if (candidate.compareTo(best) > 0) best = candidate;
        }
        System.out.println(best);
    }
}

