public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String S = br.readLine().trim();
        int M = S.length();
        int N = M / 2;

        int[] pairPosA = new int[N + 1];
        int[] pairPosB = new int[N + 1];
        int[] pairIdAtPos = new int[M];
        char[] ch = S.toCharArray();

        int cntA = 0, cntB = 0;
        for (int i = 0; i < M; i++) {
            if (ch[i] == 'a') {
                cntA++;
                pairPosA[cntA] = i;
                pairIdAtPos[i] = cntA;
            } else {
                cntB++;
                pairPosB[cntB] = i;
                pairIdAtPos[i] = cntB;
            }
        }

        // For each pair i, l[i] = min(posA, posB), r[i] = max(posA, posB)
        int[] l = new int[N + 1];
        int[] r = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            l[i] = Math.min(pairPosA[i], pairPosB[i]);
            r[i] = Math.max(pairPosA[i], pairPosB[i]);
        }

        // DP over positions:
        // dp[i] = lexicographically largest string obtainable from suffix starting at i,
        // considering only pairs whose both positions are >= i.
        // Transition:
        // - skip position i
        // - if i is the left endpoint of its pair p, take both endpoints => S[i] + dp[r[p]+1] with S[r[p]]
        // Actually resulting subsequence preserves order, so it is S[i] + (middle from i+1..r-1 impossible for p)
        // and then S[r] + suffix after r. Since other pairs crossing p cannot be taken partially, and any pair
        // fully inside (i, r) can still be chosen. Therefore:
        // take = S[i] + bestInsideThenRight, but easier to model by interval DP.
        //
        // Simpler interval DP:
        // f[L][R] = best subsequence from interval [L,R] using only pairs fully contained in [L,R].
        // But O(n^2) strings is too large.
        //
        // Key simplification:
        // The chosen set of pairs must be non-crossing in terms of intervals? No, crossing pairs can both be chosen.
        // Since every chosen pair contributes its two chars in original order.
        //
        // We can use recursion on positions with memoized strings:
        // At position i:
        //   skip i -> solve(i+1) unless i is right endpoint whose left already skipped; still okay because pair can be unchosen.
        //   take pair p only if i == l[p], result = S[l[p]] + solveBetweenAndAfter(p)
        //
        // To correctly handle inside interval before r[p], we solve on positions with a forbidden pair removed naturally:
        // Since pair p is chosen, both endpoints are fixed, and among positions (i+1..r[p]-1) we may choose any pairs fully inside.
        // Among positions after r[p], any pairs fully there.
        // Thus answer for chosen p is:
        //    best(i+1, r[p]-1) + S[r[p]] + best(r[p]+1, M-1), prefixed by S[i]
        //
        // So we need interval DP best(L,R).
        //
        // N is not stated here, but typical constraints for this task allow O(M^2) DP with compact representation.
        // We'll store strings directly.

        String[][] dp = new String[M][M];
        for (int len = 1; len <= M; len++) {
            for (int L = 0; L + len - 1 < M; L++) {
                int R = L + len - 1;
                String best = "";
                // skip L
                if (L + 1 <= R) best = dp[L + 1][R];

                int p = pairIdAtPos[L];
                if (l[p] == L && r[p] <= R) {
                    StringBuilder sb = new StringBuilder();
                    sb.append(ch[L]);
                    if (L + 1 <= r[p] - 1) sb.append(dp[L + 1][r[p] - 1]);
                    sb.append(ch[r[p]]);
                    if (r[p] + 1 <= R) sb.append(dp[r[p] + 1][R]);
                    String cand = sb.toString();
                    if (cand.compareTo(best) > 0) best = cand;
                }
                dp[L][R] = best;
            }
        }

        System.out.println(M == 0 ? "" : dp[0][M - 1]);
    }
}

