        if S[i] == 'b':
            pid = pair_of_pos[i]
            if not chosen[pid]:
                chosen[pid] = True
                ans.append('b')
            i += 1
        else:
            # At an 'a': if there exists any unchosen 'b' later,
            # skipping this 'a' is always better lexicographically.
            has_future_unchosen_b = False
            for j in range(i + 1, len(S)):
                if S[j] == 'b':
                    pid = pair_of_pos[j]
                    if not chosen[pid]:
                        has_future_unchosen_b = True
                        break

            pid = pair_of_pos[i]
            if has_future_unchosen_b:
                # skip this 'a'
                i += 1
            else:
                # no more useful 'b' later, so take this pair if not yet taken
                if not chosen[pid]:
